challenge.code:
const P = ctx.params;
const pad = ctx.chip('$orders', { color: ctx.colors.g2, textColor: 0x04101a, minWidth: 180, size: 13 });
pad.y = ctx.height - 30;
pad.x = ctx.width / 2;
ctx.stage.addChild(pad);
ctx.app.stage.eventMode = 'static';
ctx.app.stage.hitArea = new PIXI.Rectangle(0, 0, ctx.width, ctx.height);
ctx.app.stage.on('pointermove', (e) => { pad.x = Math.max(80, Math.min(ctx.width - 80, e.global.x)); });
let score = 0, lives = 3, t = 40;
const live = [];
const paint = () => ctx.api.setGoal(score + ' / ' + P.target + '  ·  lives ' + lives);
paint();
ctx.onTick((dt) => {
  t += dt;
  if (t > 40) {
    t = 0;
    const isReal = Math.random() < 0.58;
    const name = isReal ? ctx.pick(P.real) : ctx.pick(P.fake);
    const c = ctx.chip(name, { color: isReal ? ctx.colors.g1 : ctx.colors.dim, textColor: isReal ? 0x04101a : 0xdfe6ff, size: 13 });
    c.x = ctx.rand(70, ctx.width - 70);
    c.y = -20;
    c.isReal = isReal;
    ctx.stage.addChild(c);
    live.push(c);
  }
  for (let i = live.length - 1; i >= 0; i--) {
    const c = live[i];
    c.y += 2.5 * dt;
    const hit = c.y > pad.y - 22 && c.y < pad.y + 22 && Math.abs(c.x - pad.x) < 108;
    if (hit) {
      const wasReal = c.isReal;
      live.splice(i, 1);
      c.destroy();
      if (wasReal) {
        score++;
        ctx.api.setScore(score);
        paint();
        gsap.to(pad.scale, { x: 1.18, y: 1.18, duration: .12, onComplete: () => gsap.to(pad.scale, { x: 1, y: 1, duration: .2, ease: 'back.out' }) });
        if (score >= P.target) { ctx.api.win('Every one of those is on a real $http bag.'); return; }
      } else {
        lives--;
        paint();
        if (lives <= 0) { ctx.api.fail('That member does not exist on an $http bag. The body is already decoded into .data.'); return; }
      }
      continue;
    }
    if (c.y > ctx.height + 30) {
      live.splice(i, 1);
      c.destroy();
    }
  }
});

