    empty: EmptyState("No orders yet"),
    data: Table([
      Col("Id", $orders.data.map(o => o.id)),
      Col("Task", $orders.data.map(o => o.title))
    ])
  }),
  Button("Refetch", { onClick: reload, variant: "primary", icon: "rotate-right" })
]))
